function ScoringFunctions_PlayerImperialCombatUpgrade(aiPlayer)
	local player = AI_ConvertToSimPlayer(aiPlayer)
	local difficulty = AI_GetDifficulty(player)

	if (not Util_IsPlayerRace(aiPlayer, "ottoman")) then 
		return { AIProductionScoring_LuaScoringFunction(aiPlayer, alwaysReturnZero) }
	end

	local result = {
		AIProductionScoring_OnlyProduceOneAtATime(aiPlayer),
		AIProductionScoring_StrategicIntention(aiPlayer, { ["combat"] = 0.25, ["upgrade"] = 0.75 })
	}

	-- if easy then zero out this score
	if difficulty <= AID_EASY then
		return { AIProductionScoring_LuaScoringFunction(aiPlayer, alwaysReturnZero) }
	end

	return result
end

function ScoringFunctions_PlayerImperialEconUpgrade(aiPlayer)
