		return { AIProductionScoring_LuaScoringFunction(aiPlayer, alwaysReturnZero) }
	end

	local result = {
		AIProductionScoring_OnlyProduceOneAtATime(aiPlayer),
		AIProductionScoring_StrategicIntention(aiPlayer, { ["upgrade"] = 0.75, ["economy"] = 0.25 })
	}

	-- if easy then zero out this score
	if difficulty <= AID_EASY then
		return { AIProductionScoring_LuaScoringFunction(aiPlayer, alwaysReturnZero) }
