function ScoringFunctions_Cistern(aiPlayer)
	local player = AI_ConvertToSimPlayer(aiPlayer)
	local difficulty = AI_GetDifficulty(player)
	local dark_age_list = {
		AIProductionScoring_UnderCountLimit(aiPlayer, 1, -1, false),
		AIProductionScoring_LuaScoringFunction(aiPlayer, DarkAgeScoring),
	} 
	local feudal_age_list = {
		AIProductionScoring_UnderCountLimit(aiPlayer, 3, -1, false),
		AIProductionScoring_LuaScoringFunction(aiPlayer, FeudalAgeScoring)
	} 
	local castle_age_list = {
		AIProductionScoring_UnderCountLimit(aiPlayer, 4, -1, false),
		AIProductionScoring_LuaScoringFunction(aiPlayer, CastleAgeScoring)
	} 
	local imperial_age_list = {
		AIProductionScoring_UnderCountLimit(aiPlayer, 7, -1, false), 
		AIProductionScoring_LuaScoringFunction(aiPlayer, ImperialAgeScoring)
	}
	local result = {
		AIProductionScoring_StrategicIntention(aiPlayer, { ["economy"] = 1.0} )
	}
	local dark_age_scoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, dark_age_list) 
	local feudal_age_scoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, feudal_age_list) 
	local castle_age_scoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, castle_age_list) 
	local imperial_age_scoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, imperial_age_list) 

	-- get the max of the various age scorings
	result[#result+ 1] = AIProductionScoring_MaxScoringFunction(aiPlayer, { dark_age_scoring, feudal_age_scoring, castle_age_scoring, imperial_age_scoring})


	return result
end

function ScoringFunctions_BannermanSamuraiMelee(aiPlayer)
	-- produced based on presence of army of the right type
	-- require more of the the relevant units to score higher after having at least one bannerman already
	local min_list = {
		AIProductionScoring_UnderCountLimit(aiPlayer, 1, -1, true),
		AIProductionScoring_PresenceOfMyTypes(aiPlayer, {["spearman"] = 0.05, ["manatarms"] = 0.05, ["onna_bugeisha"] = 0.05}, true)
	}
	local min_score = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, min_list)
	local normal_score = AIProductionScoring_PresenceOfMyTypes(aiPlayer, {["spearman"] = 0.025, ["manatarms"] = 0.025, ["onna_bugeisha"] = 0.025}, true)

	local result = {
		AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
		AIProductionScoring_StrategicIntention(aiPlayer, { ["combat"] = 1.0}),
		AIProductionScoring_MaxScoringFunction(aiPlayer, {min_score, normal_score})
	}

	return result
end

