function ScoringFunctions_Towers_Militia(aiPlayer)
	local result =
	{
		AIProductionScoring_MaxScoringFunction(aiPlayer,
		{
			-- if we have fewer than 10, always score it at max
			AIProductionScoring_UnderCountLimit(aiPlayer, 10, -1, false),

			-- otherwise, score it higher than 0, so the AI will mix in some militia if it has fewer than 20.
			AIProductionScoring_MultiplyListScoringFunction(aiPlayer,
			{
				AIProductionScoring_UnderCountLimit(aiPlayer, 20, -1, false),
				AIProductionScoring_PresenceOfMyTypes(aiPlayer, {["military"] = 0.01}, true)
			})
		})
	}

	return result
end

