function ScoringFunctions_ResourceGenerator(aiPlayer)
        if workersOnly() or not ready('MultiplyListScoringFunction', 'MaxScoringFunction',
            'TimeToAcquire', 'StrategicIntention', 'ScarcityAndDeficiencyScore', 'MinimumGameTime',
            'IncreaseOverTime', 'UnderCountLimit', 'LuaScoringFunction', 'PlannedPlacementScoreIsMoreThan')
            or type(FeudalAgeScoring) ~= 'function' or type(CastleAgeScoring) ~= 'function' then return zero(aiPlayer) end
        local civ = race(aiPlayer)
        if civ == nil then return zero(aiPlayer) end
        -- Land need branch on all maps. Remove difficulty-only handicaps
        -- from the existing age minimums, not their time/count/age gates.
        local branches = {AIProductionScoring_MultiplyListScoringFunction(aiPlayer, {
            AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
            AIProductionScoring_StrategicIntention(aiPlayer, {economy=1.0}),
            AIProductionScoring_ScarcityAndDeficiencyScore(aiPlayer),
            AIProductionScoring_MinimumGameTime(aiPlayer, 6 * 60),
            AIProductionScoring_IncreaseOverTime(aiPlayer, 6 * 60, 5),
        })}
        if civ == 'english' then
            branches[#branches + 1] = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, {
                AIProductionScoring_MinimumGameTime(aiPlayer, 2 * 60),
                AIProductionScoring_UnderCountLimit(aiPlayer, 2, -1, false),
                AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
                AIProductionScoring_StrategicIntention(aiPlayer, {economy=1.0}),
            })
        end
        local feudal = {
            AIProductionScoring_LuaScoringFunction(aiPlayer, FeudalAgeScoring),
            AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
            AIProductionScoring_StrategicIntention(aiPlayer, {economy=1.0}),
            AIProductionScoring_MinimumGameTime(aiPlayer, 9 * 60),
        }
        if civ == 'english' then
            local late = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, {
                AIProductionScoring_UnderCountLimit(aiPlayer, 12, -1, false),
                AIProductionScoring_MinimumGameTime(aiPlayer, 13 * 60),
            })
            feudal[#feudal + 1] = AIProductionScoring_MaxScoringFunction(aiPlayer, {
                AIProductionScoring_UnderCountLimit(aiPlayer, 6, -1, false), late,
            })
        else
            feudal[#feudal + 1] = AIProductionScoring_UnderCountLimit(aiPlayer, 2, -1, false)
        end
        branches[#branches + 1] = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, feudal)
        branches[#branches + 1] = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, {
            AIProductionScoring_LuaScoringFunction(aiPlayer, CastleAgeScoring),
            AIProductionScoring_MinimumGameTime(aiPlayer, 16 * 60),
            AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
            AIProductionScoring_StrategicIntention(aiPlayer, {economy=1.0}),
            AIProductionScoring_UnderCountLimit(aiPlayer, civ == 'english' and 24 or 16, -1, false),
        })
        branches[#branches + 1] = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, {
            AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
            AIProductionScoring_StrategicIntention(aiPlayer, {economy=1.0}),
            AIProductionScoring_MinimumGameTime(aiPlayer, 35 * 60),
            AIProductionScoring_UnderCountLimit(aiPlayer, 60, -1, false),
        })
        return building(aiPlayer, {
            AIProductionScoring_MaxScoringFunction(aiPlayer, branches),
            AIProductionScoring_PlannedPlacementScoreIsMoreThan(aiPlayer, 0.2),
        })
    end
